class Solution {
public:
    int magnificentSets(int n, std::vector<std::vector<int>>& edges) {
        std::vector<std::vector<int>> adj(n + 1);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        std::vector<int> color(n + 1, 0);
        std::vector<std::vector<int>> components;
        for (int i = 1; i <= n; ++i) {
            if (color[i] != 0) continue;
            std::vector<int> comp;
            std::queue<int> q;
            q.push(i);
            color[i] = 1;
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                comp.push_back(u);
                for (int v : adj[u]) {
                    if (color[v] == 0) {
                        color[v] = -color[u];
                        q.push(v);
                    } else if (color[v] == color[u]) return -1;
                }
            }
            components.push_back(comp);
        }
        auto bfs_depth = [&](int start) {
            std::vector<int> dist(n + 1, 0);
            dist[start] = 1;
            std::queue<int> q;
            q.push(start);
            int max_d = 1;
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                int d = dist[u];
                max_d = std::max(max_d, d);
                for (int v : adj[u]) {
                    if (dist[v] == 0) {
                        dist[v] = d + 1;
                        q.push(v);
                    }
                }
            }
            return max_d;
        };
        int total_groups = 0;
        for (const auto& comp : components) {
            int best = 0;
            for (int node : comp) best = std::max(best, bfs_depth(node));
            total_groups += best;
        }
        return total_groups;
    }
};

class Solution {
    public int magnificentSets(int n, int[][] edges) {
        java.util.List<Integer>[] adj = new java.util.ArrayList[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        int[] color = new int[n + 1];
        java.util.List<java.util.List<Integer>> components = new java.util.ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (color[i] != 0) continue;
            java.util.List<Integer> comp = new java.util.ArrayList<>();
            java.util.Queue<Integer> q = new java.util.LinkedList<>();
            q.offer(i);
            color[i] = 1;
            while (!q.isEmpty()) {
                int u = q.poll();
                comp.add(u);
                for (int v : adj[u]) {
                    if (color[v] == 0) {
                        color[v] = -color[u];
                        q.offer(v);
                    } else if (color[v] == color[u]) return -1;
                }
            }
            components.add(comp);
        }
        int totalGroups = 0;
        for (java.util.List<Integer> comp : components) {
            int best = 0;
            for (int node : comp) {
                best = Math.max(best, bfsDepth(node, adj, n));
            }
            totalGroups += best;
        }
        return totalGroups;
    }
    private int bfsDepth(int start, java.util.List<Integer>[] adj, int n) {
        int[] dist = new int[n + 1];
        dist[start] = 1;
        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        q.offer(start);
        int maxD = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            int d = dist[u];
            maxD = Math.max(maxD, d);
            for (int v : adj[u]) {
                if (dist[v] == 0) {
                    dist[v] = d + 1;
                    q.offer(v);
                }
            }
        }
        return maxD;
    }
}

var magnificentSets = function(n, edges) {
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const color = new Array(n + 1).fill(0);
    const components = [];
    for (let i = 1; i <= n; i++) {
        if (color[i] !== 0) continue;
        const comp = [];
        const q = [i];
        color[i] = 1;
        while (q.length > 0) {
            const u = q.shift();
            comp.push(u);
            for (const v of adj[u]) {
                if (color[v] === 0) {
                    color[v] = -color[u];
                    q.push(v);
                } else if (color[v] === color[u]) return -1;
            }
        }
        components.push(comp);
    }
    const bfsDepth = (start) => {
        const dist = new Array(n + 1).fill(0);
        dist[start] = 1;
        const q = [start];
        let maxD = 1;
        while (q.length > 0) {
            const u = q.shift();
            const d = dist[u];
            if (d > maxD) maxD = d;
            for (const v of adj[u]) {
                if (dist[v] === 0) {
                    dist[v] = d + 1;
                    q.push(v);
                }
            }
        }
        return maxD;
    };
    let totalGroups = 0;
    for (const comp of components) {
        let best = 0;
        for (const node of comp) {
            const d = bfsDepth(node);
            if (d > best) best = d;
        }
        totalGroups += best;
    }
    return totalGroups;
};
